     1	/** Relative formatting, overdue detection and the digest window. */
     2	import { describe, expect, it } from "vitest";
     3	import {
     4	  addDays,
     5	  digestWindow,
     6	  formatDate,
     7	  formatRelative,
     8	  isOverdue,
     9	  now,
    10	  parseIso,
    11	} from "@/lib/date";
    12	import type { IsoTimestamp } from "@/types/common";
    13	
    14	const REFERENCE = new Date("2026-03-15T12:00:00.000Z");
    15	const iso = (value: string): IsoTimestamp => value as IsoTimestamp;
    16	
    17	describe("lib/date", () => {
    18	  it("round-trips now() through parseIso()", () => {
    19	    const stamp = now();
    20	    expect(parseIso(stamp).toISOString()).toBe(stamp);
    21	  });
    22	
    23	  it("throws on a malformed timestamp rather than yielding Invalid Date", () => {
    24	    expect(() => parseIso(iso("not-a-date"))).toThrow(RangeError);
    25	  });
    26	
    27	  it("formats past distances with an 'ago' suffix", () => {
    28	    expect(formatRelative(iso("2026-03-15T11:59:30.000Z"), REFERENCE)).toBe("just now");
    29	    expect(formatRelative(iso("2026-03-15T11:55:00.000Z"), REFERENCE)).toBe("5 minutes ago");
    30	    expect(formatRelative(iso("2026-03-15T11:00:00.000Z"), REFERENCE)).toBe("1 hour ago");
    31	    expect(formatRelative(iso("2026-03-13T12:00:00.000Z"), REFERENCE)).toBe("2 days ago");
    32	    expect(formatRelative(iso("2026-03-01T12:00:00.000Z"), REFERENCE)).toBe("2 weeks ago");
    33	  });
    34	
    35	  it("formats future distances with an 'in' prefix", () => {
    36	    expect(formatRelative(iso("2026-03-15T12:30:00.000Z"), REFERENCE)).toBe("in 30 minutes");
    37	    expect(formatRelative(iso("2026-03-18T12:00:00.000Z"), REFERENCE)).toBe("in 3 days");
    38	  });
    39	
    40	  it("renders an absolute date in the requested timezone", () => {
    41	    expect(formatDate(iso("2026-03-15T23:30:00.000Z"))).toBe("15 Mar 2026");
    42	    expect(formatDate(iso("2026-03-15T23:30:00.000Z"), "Asia/Tokyo")).toBe("16 Mar 2026");
    43	  });
    44	
    45	  it("treats a null due date as never overdue", () => {
    46	    expect(isOverdue(null, REFERENCE)).toBe(false);
    47	    expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(true);
    48	    expect(isOverdue(iso("2026-03-15T12:00:01.000Z"), REFERENCE)).toBe(false);
    49	  });
    50	
    51	  it("adds and subtracts whole days", () => {
    52	    expect(addDays(iso("2026-03-15T12:00:00.000Z"), 3)).toBe("2026-03-18T12:00:00.000Z");
    53	    expect(addDays(iso("2026-03-01T12:00:00.000Z"), -1)).toBe("2026-02-28T12:00:00.000Z");
    54	  });
    55	
    56	  it("ends the digest window at today's digest hour once it has passed", () => {
    57	    const window = digestWindow(8, REFERENCE);
    58	    expect(window.end).toBe("2026-03-15T08:00:00.000Z");
    59	    expect(window.start).toBe("2026-03-14T08:00:00.000Z");
    60	  });
    61	
    62	  it("falls back to yesterday's window when the digest hour has not arrived", () => {
    63	    const window = digestWindow(20, REFERENCE);
    64	    expect(window.end).toBe("2026-03-14T20:00:00.000Z");
    65	    expect(window.start).toBe("2026-03-13T20:00:00.000Z");
    66	  });
    67	
    68	  it("rejects a digest hour outside 0-23", () => {
    69	    expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
    70	    expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
    71	  });
    72	});
