    57	 */
    58	export function livePredicate(
    59	  column: SQLiteColumn,
    60	  scope: ArchiveScope,
--- activity page
     1	/**
     2	 * Organization activity feed; requires `activity:read` and the `activity_feed`
     3	 * flag.
     4	 *
     5	 * Owner D. Two gates that fail differently on purpose: a missing permission is
     6	 * a 404 (the page should not exist for you), a disabled flag is an explanation
     7	 * (the page exists, your plan does not include it).
     8	 *
     9	 * Must call (do not reimplement): can, isEnabled
    10	 */
    11	
    12	import { notFound } from "next/navigation";
    13	import type { Metadata } from "next";
    14	import { ActivityFeed } from "@/components/domain/activity/activity-feed";
    15	import { EmptyState } from "@/components/ui/empty-state";
    16	import { isEnabled } from "@/lib/feature-flags";
    17	import { can } from "@/lib/permissions";
    18	import { groupByDay, listActivity } from "@/server/services/activity-service";
    19	import { buildFlagContext } from "@/server/services/feature-flag-service";
    20	import { listMembers } from "@/server/services/member-service";
    21	import { searchParamsPaginationSchema } from "@/schemas/pagination";
    22	import type { User } from "@/types/member";
    23	import { loadTenantContext } from "../_lib/tenant-context";
    24	
    25	type PageParams = { orgSlug: string };
    26	
    27	export const dynamic = "force-dynamic";
    28	
    29	export const metadata: Metadata = {
    30	  title: "Activity",
    31	};
    32	
    33	const MEMBER_LOOKUP_LIMIT = 100;
    34	
    35	export default async function Page(props: {
    36	  params: Promise<PageParams>;
    37	  searchParams: Promise<Record<string, string | string[] | undefined>>;
    38	}) {
    39	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
    40	  const { orgSlug } = await props.params;
    41	  const search = await props.searchParams;
    42	
    43	  const { org, actor } = await loadTenantContext(orgSlug);
    44	
    45	  if (!can(actor, "activity:read", { kind: "activity", orgId: org.id })) {
    46	    notFound();
    47	  }
    48	
    49	  if (!isEnabled("activity_feed", buildFlagContext(actor, org))) {
    50	    return (
    51	      <EmptyState
    52	        title="The activity feed is not part of this plan"
    53	        description="Upgrade in Settings → Billing to keep an audit trail of every change."
    54	      />
    55	    );
    56	  }
    57	
    58	  const pagination = searchParamsPaginationSchema.parse(search);
    59	
    60	  const [page, members] = await Promise.all([
    61	    listActivity(actor, {
    62	      orgId: org.id,
    63	      limit: pagination.perPage,
    64	      cursor: pagination.cursor ?? null,
    65	    }),
    66	    listMembers(actor, { orgId: org.id, limit: MEMBER_LOOKUP_LIMIT }),
    67	  ]);
    68	
    69	  const actors: Record<string, User> = {};
    70	  for (const member of members.items) {
    71	    actors[member.userId] = member.user;
    72	  }
    73	
    74	  return (
    75	    <div className="space-y-8">
    76	      <header>
    77	        <h1 className="text-2xl font-semibold tracking-tight">Activity</h1>
    78	        <p className="mt-1 text-sm text-slate-600">
    79	          Every change made in {org.name}, newest first.
    80	        </p>
    81	      </header>
    82	
    83	      <ActivityFeed groups={groupByDay(page.items)} actors={actors} actor={actor} />
    84	    </div>
    85	  );
    86	}
--- panel page
     1	/**
     2	 * Default content of the side panel slot.
     3	 *
     4	 * Owner D. Matches `/[orgSlug]`, so the overview page gets an activity rail
     5	 * alongside it. The feed is a separate render tree from the main page, which is
     6	 * the point of the parallel route: a slow activity query cannot hold up the
     7	 * overview.
     8	 *
     9	 * The panel is `activity_feed`-gated; when the flag is off it renders nothing
    10	 * and the aside collapses.
    11	 */
    12	
    13	import { isEnabled } from "@/lib/feature-flags";
    14	import { can } from "@/lib/permissions";
    15	import { buildFlagContext } from "@/server/services/feature-flag-service";
    16	import { groupByDay, listActivity } from "@/server/services/activity-service";
    17	import { loadTenantContext } from "../_lib/tenant-context";
    18	
    19	type PageParams = { orgSlug: string };
    20	
    21	export const dynamic = "force-dynamic";
    22	
    23	const PANEL_ACTIVITY_LIMIT = 15;
    24	
    25	export default async function Page(props: {
    26	  params: Promise<PageParams>;
    27	  searchParams: Promise<Record<string, string | string[] | undefined>>;
    28	}) {
    29	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
    30	  const { orgSlug } = await props.params;
    31	  await props.searchParams;
    32	
    33	  const { org, actor } = await loadTenantContext(orgSlug);
    34	
    35	  if (!isEnabled("activity_feed", buildFlagContext(actor, org))) {
    36	    return null;
    37	  }
    38	  if (!can(actor, "activity:read", { kind: "activity", orgId: org.id })) {
    39	    return null;
    40	  }
    41	
    42	  const page = await listActivity(actor, {
    43	    orgId: org.id,
    44	    limit: PANEL_ACTIVITY_LIMIT,
    45	  });
    46	  const groups = groupByDay(page.items);
    47	
    48	  return (
    49	    <section className="p-6">
    50	      <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
    51	        Recent activity
    52	      </h2>
    53	
    54	      <div className="mt-4 space-y-6">
    55	        {groups.map((group) => (
    56	          <div key={group.day}>
    57	            <p className="text-xs uppercase tracking-wide text-slate-400">
    58	              {group.day}
    59	            </p>
    60	            <ul className="mt-2 space-y-2 text-sm text-slate-600">
    61	              {group.events.map((event) => (
    62	                <li key={event.id}>{event.summary}</li>
    63	              ))}
    64	            </ul>
    65	          </div>
    66	        ))}
    67	      </div>
    68	    </section>
    69	  );
    70	}

