  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The window a digest covers, on `timeZone`'s clock. It ends at the most recent
 * `digestHour:00` at or before `reference`: today's if that hour has passed,
 * yesterday's otherwise — so a job run early never mails an empty digest and
 * then skips the real one. It starts at the same hour on the previous calendar
 * day, which makes it 23 or 25 hours long across a DST change.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digest hour must be 0-23, got ${digestHour}`);
  }

  let endWall = wallMidnight(reference, 0, timeZone) + digestHour * HOUR_MS;
  if (instantOfWallClock(endWall, timeZone) > reference.getTime()) {
    endWall -= DAY_MS;
  }

  return {
    start: toIsoTimestamp(new Date(instantOfWallClock(endWall - DAY_MS, timeZone))),
    end: toIsoTimestamp(new Date(instantOfWallClock(endWall, timeZone))),
  };
}

