/**
 * Columns added after their table first shipped. `CREATE TABLE IF NOT EXISTS`
 * never alters a table that already exists, so these are added when missing;
 * existing rows take the default.
 */
const ADDED_COLUMNS: readonly {
  table: string;
  column: string;
  definition: string;
}[] = [
  { table: "organizations", column: "time_zone", definition: "TEXT NOT NULL DEFAULT 'UTC'" },
];

/**
 * Brings `databasePath` up to date. Generated migrations win when they exist;
 * otherwise the embedded schema is pushed. Safe to run repeatedly — every
 * statement is `IF NOT EXISTS`, and a column is only added when it is absent.
 */
export async function runMigrations(
  databasePath: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH,
): Promise<void> {
  const absolute = resolve(process.cwd(), databasePath);
  mkdirSync(dirname(absolute), { recursive: true });

  const sqlite = new Database(absolute);
  sqlite.pragma("journal_mode = WAL");

  try {
    for (const statement of readMigrationStatements()) {
      sqlite.exec(statement);
    }
    addMissingColumns(sqlite);
  } finally {
    sqlite.close();
  }
}

function addMissingColumns(sqlite: Database.Database): void {
  for (const { table, column, definition } of ADDED_COLUMNS) {
    const existing = sqlite.pragma(`table_info(${table})`) as readonly { name: string }[];
    if (existing.some((row) => row.name === column)) continue;
    sqlite.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`);
  }
}

