it("treats a null due date as never overdue", () => {
  expect(isOverdue(null, REFERENCE)).toBe(false);
});

it("keeps a due day open for the whole of that day", () => {
  expect(isOverdue(iso("2026-03-15T00:00:00.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T23:59:59.000Z"), REFERENCE)).toBe(false);
});

it("becomes overdue once the due day has ended", () => {
  expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
  expect(isOverdue(iso("2026-03-14T00:00:00.000Z"), REFERENCE)).toBe(true);
});

it("judges the due day on the workspace clock", () => {
  // 01:00 on 16 Mar in Tokyo, but still 16:00 on 15 Mar in UTC.
  const lateInTokyo = new Date("2026-03-15T16:00:00.000Z");
  // 19:00 on 15 Mar in Tokyo.
  const dueEveningOf15th = iso("2026-03-15T10:00:00.000Z");

  expect(isOverdue(dueEveningOf15th, lateInTokyo)).toBe(false);
  expect(isOverdue(dueEveningOf15th, lateInTokyo, "Asia/Tokyo")).toBe(true);
});

it("keeps a New York evening within the same calendar day", () => {
  // 23:00 on 14 Mar in New York, already the 15th in UTC.
  const lateInNewYork = new Date("2026-03-15T03:00:00.000Z");
  // 08:00 on 14 Mar in New York.
  const dueMorningOf14th = iso("2026-03-14T12:00:00.000Z");

  expect(isOverdue(dueMorningOf14th, lateInNewYork, "America/New_York")).toBe(false);
  expect(isOverdue(dueMorningOf14th, lateInNewYork)).toBe(true);
});

it("reads the calendar date of an instant on a zone's clock", () => {
  const instant = iso("2026-03-15T23:30:00.000Z");

  expect(localDate(instant, "UTC")).toBe("2026-03-15");
  expect(localDate(instant, "Asia/Tokyo")).toBe("2026-03-16");
  expect(localDate(instant, "America/New_York")).toBe("2026-03-15");
});

it("reads the hour on a zone's clock", () => {
  expect(localHour(REFERENCE, "UTC")).toBe(12);
  expect(localHour(REFERENCE, "Asia/Tokyo")).toBe(21);
});

it("finds where the zone's calendar day began", () => {
  expect(startOfLocalDay(REFERENCE, "UTC")).toBe("2026-03-15T00:00:00.000Z");
  expect(startOfLocalDay(REFERENCE, "Asia/Tokyo")).toBe("2026-03-14T15:00:00.000Z");
  expect(startOfLocalDay(REFERENCE, "America/New_York")).toBe("2026-03-15T04:00:00.000Z");
});

it("measures a DST day by its real length", () => {
  const newYork = "America/New_York";

  // The 8 Mar 2026 spring-forward day runs 05:00Z to 04:00Z: 23 hours.
  expect(startOfLocalDay(new Date("2026-03-08T15:00:00.000Z"), newYork)).toBe(
    "2026-03-08T05:00:00.000Z",
  );
  expect(startOfLocalDay(new Date("2026-03-09T12:00:00.000Z"), newYork)).toBe(
    "2026-03-09T04:00:00.000Z",
  );
});

it("places a day that opens on a midnight clock jump at the jump", () => {
  // Santiago's clocks go from 00:00 straight to 01:00 on 6 Sep 2026.
  expect(startOfLocalDay(new Date("2026-09-06T15:00:00.000Z"), "America/Santiago")).toBe(
    "2026-09-06T04:00:00.000Z",
  );
});

it("counts calendar days back to local midnight", () => {
  expect(startOfLocalDaysAgo(REFERENCE, 30, "UTC")).toBe("2026-02-13T00:00:00.000Z");
  // Seven calendar days before 15 Mar is 8 Mar, which opens at 00:00 EST.
  expect(startOfLocalDaysAgo(REFERENCE, 7, "America/New_York")).toBe(
    "2026-03-08T05:00:00.000Z",
  );
});

it("recognises IANA zone names only", () => {
  expect(isValidTimeZone("UTC")).toBe(true);
  expect(isValidTimeZone("Asia/Tokyo")).toBe(true);
  expect(isValidTimeZone("Mars/Olympus")).toBe(false);
});

