/**
 * Each workspace's zone, end to end: it is stored with the other settings, and
 * it decides which day an issue is overdue on, both in the overdue sweep and in
 * the project counter.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as orgService from "@/server/services/organization-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

/** 01:00 on 16 Mar in Tokyo, while it is still 16:00 on 15 Mar in UTC. */
const LATE_IN_TOKYO = new Date("2026-03-15T16:00:00.000Z");
/** 19:00 on 15 Mar in Tokyo, 10:00 on 15 Mar in UTC. */
const DUE_EVENING_OF_15TH = "2026-03-15T10:00:00.000Z";

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

/** A tenant whose workspace runs on `timeZone`, registered for the rollup sweeps. */
async function makeTenant(slug: string, timeZone: string): Promise<Tenant> {
  const tenant = await createTenant(slug);
  await orgService.updateOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    settings: { timeZone },
  });
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

describe("workspace clock", () => {
  it("stores the zone with the other settings and keeps it across a partial save", async () => {
    const tenant = await makeTenant("clock-stored", "Asia/Tokyo");

    const saved = await orgService.updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 9 },
    });

    expect(saved.settings.timeZone).toBe("Asia/Tokyo");
    expect(saved.settings.digestHourUtc).toBe(9);
    const reread = await orgRepo.findOrgById(tenant.org.id);
    expect(reread?.settings.timeZone).toBe("Asia/Tokyo");
  });

  it("defaults a new workspace to UTC", async () => {
    const tenant = await createTenant("clock-default");
    expect(tenant.org.settings.timeZone).toBe("UTC");
  });

  it("refuses a zone Intl does not recognise and changes nothing", async () => {
    const tenant = await makeTenant("clock-refused", "Europe/Paris");

    await expect(
      orgService.updateOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        settings: { timeZone: "Mars/Olympus" },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    const reread = await orgRepo.findOrgById(tenant.org.id);
    expect(reread?.settings.timeZone).toBe("Europe/Paris");
  });

  it("counts an open issue as overdue in the project stats once its day ends on the workspace clock", async () => {
    const tenant = await makeTenant("clock-stats", "Asia/Tokyo");
    const member = tenant.actors.member;

    const dueTonight = await issueService.createIssue(
      member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Due last night", dueAt: DUE_EVENING_OF_15TH }),
    );
    const closed = await issueService.createIssue(
      member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Closed", dueAt: DUE_EVENING_OF_15TH }),
    );
    await issueService.changeIssueStatus(member, {
      orgId: tenant.org.id,
      issueId: closed.id,
      status: "done",
    });
    await issueService.createIssue(
      member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Due later today", dueAt: "2026-03-15T20:00:00.000Z" }),
    );

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(LATE_IN_TOKYO);

    const { stats } = await projectService.getProject(member, tenant.org.id, tenant.project.slug);
    expect(stats.overdueIssues).toBe(1);
    expect(dueTonight.dueAt).toBe(DUE_EVENING_OF_15TH);
  });

  it("sweeps an issue as overdue only in the workspace whose day has ended", async () => {
    const tokyo = await makeTenant("clock-sweep-tokyo", "Asia/Tokyo");
    const utc = await makeTenant("clock-sweep-utc", "UTC");

    const tokyoIssue = await issueService.createIssue(
      tokyo.actors.member,
      issueInput(tokyo.org.id, tokyo.project.id, { title: "Tokyo late", dueAt: DUE_EVENING_OF_15TH }),
    );
    const utcIssue = await issueService.createIssue(
      utc.actors.member,
      issueInput(utc.org.id, utc.project.id, { title: "UTC late", dueAt: DUE_EVENING_OF_15TH }),
    );

    const seen: Array<{ orgId: string; issueId: string }> = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push({ orgId: payload.orgId, issueId: payload.issueId });
      }),
    );

    await runOverdueIssueJob(LATE_IN_TOKYO);

    expect(seen).toContainEqual({ orgId: tokyo.org.id, issueId: tokyoIssue.id });
    expect(seen).not.toContainEqual({ orgId: utc.org.id, issueId: utcIssue.id });
  });
});

