/** Organization settings: the zone defaults to UTC, unknown zones are refused, and a partial save never resets it. */
import { describe, expect, it } from "vitest";
import {
  organizationSettingsSchema,
  updateOrganizationSchema,
} from "@/schemas/organization";
import { ORG_A } from "../helpers/factories";

describe("schemas/organization", () => {
  it("defaults the workspace time zone to UTC", () => {
    expect(organizationSettingsSchema.parse({}).timeZone).toBe("UTC");
  });

  it("accepts an IANA zone name", () => {
    expect(organizationSettingsSchema.parse({ timeZone: "Asia/Tokyo" }).timeZone).toBe(
      "Asia/Tokyo",
    );
  });

  it("rejects a zone name Intl does not recognise", () => {
    expect(organizationSettingsSchema.safeParse({ timeZone: "Mars/Olympus" }).success).toBe(
      false,
    );
    expect(
      updateOrganizationSchema.safeParse({
        orgId: ORG_A,
        settings: { timeZone: "Mars/Olympus" },
      }).success,
    ).toBe(false);
  });

  it("leaves the zone unset in a partial update that does not name it", () => {
    const parsed = updateOrganizationSchema.parse({
      orgId: ORG_A,
      settings: { digestHourUtc: 9 },
    });

    expect(parsed.settings?.digestHourUtc).toBe(9);
    expect(parsed.settings?.timeZone).toBeUndefined();
  });
});

