4	import Link from "next/link";
5	import { Avatar } from "@/components/ui/avatar";
6	import { Badge } from "@/components/ui/badge";
7	import { Card } from "@/components/ui/card";
8	import { cn } from "@/lib/cn";
9	import { formatRelative, isOverdue } from "@/lib/date";
10	import { humanizePriority, humanizeStatus } from "@/lib/format";
11	import type { Issue, IssueLabel, IssuePriority } from "@/types/issue";
12	import type { User } from "@/types/member";
13	import type { ReactElement } from "react";
14	import { PRIORITY_TONE, STATUS_TONE } from "./issue-tone";
15	
16	export type IssueCardProps = {
17	  issue: Issue;
18	  assignee?: User | null;
19	  labels?: readonly IssueLabel[];
20	  href: string;
21	  compact?: boolean;
22	};
23	
24	/** Priorities worth shouting about; `none`/`low` stay silent on a card. */
25	function shouldShowPriority(priority: IssuePriority): boolean {
26	  return priority !== "none" && priority !== "low";
27	}
28	
29	export function IssueCard(props: IssueCardProps): ReactElement | null {
30	  const { issue, assignee = null, labels = [], href, compact = false } = props;
31	  const overdue = isOverdue(issue.dueAt);
32	
33	  return (
34	    <Card padded={!compact} className="issue-card">
35	      <div className={cn("flex items-start gap-3", compact && "text-sm")}>
36	        <div className="min-w-0 flex-1">
37	          <Link href={href} className="block font-medium hover:underline">
38	            <span className="mr-2 text-neutral-500">#{issue.number}</span>
39	            {issue.title}
40	          </Link>
41	
42	          <div className="mt-1 flex flex-wrap items-center gap-2">
43	            <Badge tone={STATUS_TONE[issue.status]} size="sm">
44	              {humanizeStatus(issue.status)}
45	            </Badge>
46	
47	            {shouldShowPriority(issue.priority) ? (
48	              <Badge tone={PRIORITY_TONE[issue.priority]} size="sm">
49	                {humanizePriority(issue.priority)}
50	              </Badge>
51	            ) : null}
52	
53	            {labels.map((label) => (
54	              <Badge key={label.id} tone="neutral" size="sm">
55	                {label.name}
56	              </Badge>
57	            ))}
58	
59	            {issue.dueAt !== null ? (
60	              <span className={cn("text-xs", overdue && "text-red-600")}>
61	                {overdue ? "overdue " : "due "}
62	                {formatRelative(issue.dueAt)}
63	              </span>
64	            ) : null}
65	
66	            {issue.archivedAt !== null ? (
67	              <Badge tone="warning" size="sm">
68	                Archived
69	              </Badge>
70	            ) : null}
71	          </div>
72	        </div>
73	
74	        {assignee !== null ? (
75	          <Avatar name={assignee.name} src={assignee.avatarUrl} size="sm" />
76	        ) : (
77	          <Badge tone="neutral" size="sm">
78	            Unassigned
79	          </Badge>
80	        )}
81	      </div>
82	    </Card>
83	  );
84	}
