20	import { organizationResource } from "../permission/resources";
21	import { IssueRow } from "./issue-row";
22	
23	export type IssueListProps = {
24	  issues: readonly IssueWithRelations[];
25	  actor: Actor;
26	  emptyLabel?: string;
27	  onArchive?: (issueId: IssueId) => void;
28	  /** Assignee lookup for the rows; the page joins users once, not per row. */
29	  users?: Readonly<Record<string, User>>;
30	};
31	
32	const COLUMNS: readonly string[] = [
33	  "#",
34	  "Title",
35	  "Status",
36	  "Priority",
37	  "Assignee",
38	  "Due",
39	  "",
40	];
41	
42	export function IssueList(props: IssueListProps): ReactElement | null {
43	  const { issues, actor, emptyLabel, onArchive, users = {} } = props;
44	
45	  // One coarse check for the whole list: an actor who cannot read issues at
46	  // all sees the empty state rather than a table of hidden rows.
47	  if (!can(actor, "issue:read", organizationResource(actor.orgId))) {
48	    return (
49	      <EmptyState
50	        title="No access"
51	        description="Your role does not include issue access in this organization."
52	      />
53	    );
54	  }
55	
56	  if (issues.length === 0) {
57	    return (
58	      <EmptyState
59	        title={emptyLabel ?? "No issues match this filter"}
60	        description="Adjust the filters or create the first issue."
61	      />
62	    );
63	  }
64	
65	  // Live rows first; archived ones stay visible but sink to the bottom.
66	  const ordered = [...issues].sort((a, b) => {
67	    const archivedDelta =
68	      Number(isArchived(a.issue)) - Number(isArchived(b.issue));
69	    if (archivedDelta !== 0) return archivedDelta;
70	    return b.issue.updatedAt.localeCompare(a.issue.updatedAt);
71	  });
72	
73	  return (
74	    <Table caption="Issues">
75	      <TableHead>
