toolUseResult.originalFile:
/**
 * Timestamp helpers: ISO round-tripping, relative formatting, and the calendar
 * arithmetic — due dates, digest windows, retention cut-offs — taken on a
 * workspace's own clock.
 *
 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
 * a SQLite text column). Nothing outside this module constructs a `Date` from
 * a stored value — going through `parseIso()` keeps the "what if it is
 * malformed" answer in one place.
 *
 * A day is always a calendar day on the clock of the IANA zone the caller
 * passes in. The zone's wall clock is read through `Intl`, so a 23- or 25-hour
 * day across a DST change needs no special case.
 */
import type { IsoTimestamp } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const SECOND_MS = 1_000;
const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

/** One formatter per zone: building one costs far more than using it. */
const wallClocks = new Map<string, Intl.DateTimeFormat>();

/** Throws a RangeError for a zone name `Intl` does not recognise. */
function wallClock(timeZone: string): Intl.DateTimeFormat {
  let format = wallClocks.get(timeZone);
  if (format === undefined) {
    format = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "numeric",
      day: "numeric",
      hour: "numeric",
      minute: "numeric",
      second: "numeric",
    });
    wallClocks.set(timeZone, format);
  }
  return format;
}

/** True when `Intl` recognises `timeZone` as an IANA zone name. */
export function isValidTimeZone(timeZone: string): boolean {
  try {
    wallClock(timeZone);
    return true;
  } catch {
    return false;
  }
}

export function now(): IsoTimestamp {
  return toIsoTimestamp(new Date());
}

/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
export function parseIso(value: IsoTimestamp): Date {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
  }
  return date;
}

function plural(count: number, unit: string): string {
  return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/**
 * "just now" / "5 minutes ago" / "in 2 days" — the wording the activity feed,
 * issue cards and comment headers all use.
 */
export function formatRelative(
  value: IsoTimestamp,
  reference: Date = new Date(),
): string {
  const deltaMs = parseIso(value).getTime() - reference.getTime();
  const past = deltaMs < 0;
  const abs = Math.abs(deltaMs);

  const phrase = ((): string => {
    if (abs < MINUTE_MS) return "just now";
    if (abs < HOUR_MS) return plural(Math.floor(abs / MINUTE_MS), "minute");
    if (abs < DAY_MS) return plural(Math.floor(abs / HOUR_MS), "hour");
    if (abs < WEEK_MS) return plural(Math.floor(abs / DAY_MS), "day");
    if (abs < 30 * DAY_MS) return plural(Math.floor(abs / WEEK_MS), "week");
    if (abs < 365 * DAY_MS) return plural(Math.floor(abs / (30 * DAY_MS)), "month");
    return plural(Math.floor(abs / (365 * DAY_MS)), "year");
  })();

  if (phrase === "just now") return phrase;
  return past ? `${phrase} ago` : `in ${phrase}`;
}

/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

/**
 * The zone's wall-clock reading at `instant`, as the UTC milliseconds that
 * would show the same date and time. Offsets are whole seconds at the finest,
 * so the reading is exact to the second.
 */
function wallClockMs(instant: number, timeZone: string): number {
  if (timeZone === "UTC") return instant;

  const parts = wallClock(timeZone).formatToParts(instant);
  const field = (type: Intl.DateTimeFormatPartTypes): number =>
    Number(parts.find((part) => part.type === type)?.value);

  return Date.UTC(
    field("year"),
    field("month") - 1,
    field("day"),
    field("hour"),
    field("minute"),
    field("second"),
  );
}

/** The `YYYY-MM-DD` calendar date of `instant` on the zone's clock. */
function calendarDateOf(instant: number, timeZone: string): string {
  return new Date(wallClockMs(instant, timeZone)).toISOString().slice(0, 10);
}

/**
 * Midnight, as a wall-clock reading, of the calendar day `days` before the one
 * `reference` falls on in `timeZone`.
 */
function wallMidnight(reference: Date, days: number, timeZone: string): number {
  const [year, month, day] = calendarDateOf(reference.getTime(), timeZone)
    .split("-")
    .map(Number);
  return Date.UTC(year, month - 1, day - days);
}

/**
 * The first instant at which the zone's wall clock reads `wallMs` or later.
 * When that reading never occurs (a spring-forward gap) this is the moment the
 * clock jumps past it, so a missing 02:00 resolves to 03:00.
 */
function instantOfWallClock(wallMs: number, timeZone: string): number {
  // Real offsets stay within ±14 hours, so the answer lies within two days.
  let low = wallMs - 2 * DAY_MS;
  let high = wallMs + 2 * DAY_MS;
  while (high - low > SECOND_MS) {
    const middle = low + Math.floor((high - low) / SECOND_MS / 2) * SECOND_MS;
    if (wallClockMs(middle, timeZone) >= wallMs) {
      high = middle;
    } else {
      low = middle;
    }
  }
  return high;
}

/** The `YYYY-MM-DD` calendar date of `value` on `timeZone`'s clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  return calendarDateOf(parseIso(value).getTime(), timeZone);
}

/** The hour, 0-23, on `timeZone`'s clock at `reference`. */
export function localHour(reference: Date, timeZone: string): number {
  return new Date(wallClockMs(reference.getTime(), timeZone)).getUTCHours();
}

/**
 * The instant at which the calendar day `days` before the one containing
 * `reference` began, on `timeZone`'s clock. `days = 0` is today.
 */
export function startOfLocalDaysAgo(
  reference: Date,
  days: number,
  timeZone: string,
): IsoTimestamp {
  const start = instantOfWallClock(wallMidnight(reference, days, timeZone), timeZone);
  return toIsoTimestamp(new Date(start));
}

/** The instant at which the calendar day containing `reference` began, on `timeZone`'s clock. */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return startOfLocalDaysAgo(reference, 0, timeZone);
}

/**
 * True when a due date exists and the calendar day it falls on, on
 * `timeZone`'s clock, has ended by `reference`. A due date is a whole day: on
 * that day itself the issue is not overdue, whatever time of day it names.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < calendarDateOf(reference.getTime(), timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The window a digest covers, on `timeZone`'s clock. It ends at the most recent
 * `digestHour:00` at or before `reference`: today's if that hour has passed,
 * yesterday's otherwise — so a job run early never mails an empty digest and
 * then skips the real one. It starts at the same hour on the previous calendar
 * day, which makes it 23 or 25 hours long across a DST change.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digest hour must be 0-23, got ${digestHour}`);
  }

  let endWall = wallMidnight(reference, 0, timeZone) + digestHour * HOUR_MS;
  if (instantOfWallClock(endWall, timeZone) > reference.getTime()) {
    endWall -= DAY_MS;
  }

  return {
    start: toIsoTimestamp(new Date(instantOfWallClock(endWall - DAY_MS, timeZone))),
    end: toIsoTimestamp(new Date(instantOfWallClock(endWall, timeZone))),
  };
}

