/**
 * A database created before workspaces had a time zone gains the column on the
 * next migration, and its existing organizations read back as UTC.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import Database from "better-sqlite3";
import { describe, expect, it } from "vitest";
import { runMigrations } from "@/server/db/migrate";

describe("db/migrate", () => {
  it("adds the organization time zone to an existing table, defaulting to UTC", async () => {
    const dir = mkdtempSync(join(tmpdir(), "taskflow-migrate-"));
    const path = join(dir, "taskflow.db");

    try {
      const legacy = new Database(path);
      legacy.exec(`
        CREATE TABLE organizations (
          id TEXT PRIMARY KEY NOT NULL,
          name TEXT NOT NULL,
          slug TEXT NOT NULL,
          owner_id TEXT NOT NULL,
          plan TEXT NOT NULL DEFAULT 'free',
          logo_url TEXT,
          trial_ends_at TEXT,
          default_issue_status TEXT NOT NULL DEFAULT 'backlog',
          allow_public_projects INTEGER NOT NULL DEFAULT 0,
          require_two_factor INTEGER NOT NULL DEFAULT 0,
          digest_hour_utc INTEGER NOT NULL DEFAULT 7,
          enabled_flag_overrides TEXT NOT NULL DEFAULT '[]',
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          archived_at TEXT
        )
      `);
      legacy.exec(`
        INSERT INTO organizations (id, name, slug, owner_id, created_at, updated_at)
        VALUES ('org_legacy', 'Acme', 'acme', 'usr_1', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
      `);
      legacy.close();

      await runMigrations(path);
      await runMigrations(path);

      const upgraded = new Database(path);
      try {
        const row = upgraded
          .prepare("SELECT time_zone FROM organizations WHERE id = 'org_legacy'")
          .get();
        expect(row).toEqual({ time_zone: "UTC" });
      } finally {
        upgraded.close();
      }
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

