import type {
  AttachmentId,
  IsoTimestamp,
  IssueId,
  LabelId,
  ProjectId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type IssueStatus =
  | "backlog"
  | "todo"
  | "in_progress"
  | "in_review"
  | "done"
  | "canceled";

export const ISSUE_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
];

/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export type IssuePriority = "none" | "low" | "medium" | "high" | "urgent";

export const ISSUE_PRIORITIES: readonly IssuePriority[] = [
  "none",
  "low",
  "medium",
  "high",
  "urgent",
];

export interface Issue extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: IssueId;
  readonly projectId: ProjectId;
  readonly number: number;
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly authorId: UserId;
  readonly assigneeId: UserId | null;
  readonly parentId: IssueId | null;
  readonly estimate: number | null;
  readonly dueAt: IsoTimestamp | null;
  readonly startedAt: IsoTimestamp | null;
  readonly completedAt: IsoTimestamp | null;
  readonly labelIds: readonly LabelId[];
}

export interface IssueLabel extends TenantScoped {
  readonly id: LabelId;
  readonly name: string;
  readonly color: string;
  readonly description: string | null;
}

export interface IssueAttachment extends Timestamps, TenantScoped {
  readonly id: AttachmentId;
  readonly issueId: IssueId;
  readonly filename: string;
  readonly contentType: string;
  readonly sizeBytes: number;
  readonly uploadedBy: UserId;
}

/** Filter accepted by the issue repository, service layer and list UI alike. */
export interface IssueFilter {
  readonly projectId?: ProjectId;
  readonly status?: readonly IssueStatus[];
  readonly priority?: readonly IssuePriority[];
  readonly assigneeId?: UserId | null;
  readonly authorId?: UserId;
  readonly labelIds?: readonly LabelId[];
  readonly query?: string;
  readonly dueBefore?: IsoTimestamp;
  readonly includeArchived?: boolean;
}

export interface IssueWithRelations {
  readonly issue: Issue;
  readonly labels: readonly IssueLabel[];
  readonly commentCount: number;
  readonly attachmentCount: number;
}

/** One column of the kanban board; the board is an ordered list of these. */
export interface IssueBoardColumn {
  readonly status: IssueStatus;
  readonly issues: readonly Issue[];
  readonly total: number;
}

/**
 * Compact issue summary tile used by lists and the board.
 */
import Link from "next/link";
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/cn";
import { formatRelative, isOverdue } from "@/lib/date";
import { humanizePriority, humanizeStatus } from "@/lib/format";
import type { Issue, IssueLabel, IssuePriority } from "@/types/issue";
import type { User } from "@/types/member";
import type { ReactElement } from "react";
import { PRIORITY_TONE, STATUS_TONE } from "./issue-tone";

export type IssueCardProps = {
  issue: Issue;
  assignee?: User | null;
  labels?: readonly IssueLabel[];
  href: string;
  compact?: boolean;
  /** The workspace's IANA zone, which decides when the due day has ended. */
  timeZone?: string;
};

/** Priorities worth shouting about; `none`/`low` stay silent on a card. */
function shouldShowPriority(priority: IssuePriority): boolean {
  return priority !== "none" && priority !== "low";
}

export function IssueCard(props: IssueCardProps): ReactElement | null {
  const { issue, assignee = null, labels = [], href, compact = false, timeZone = "UTC" } = props;
  const overdue = isOverdue(issue.dueAt, new Date(), timeZone);

  return (
    <Card padded={!compact} className="issue-card">
      <div className={cn("flex items-start gap-3", compact && "text-sm")}>
        <div className="min-w-0 flex-1">
          <Link href={href} className="block font-medium hover:underline">
            <span className="mr-2 text-neutral-500">#{issue.number}</span>
            {issue.title}
          </Link>

          <div className="mt-1 flex flex-wrap items-center gap-2">
            <Badge tone={STATUS_TONE[issue.status]} size="sm">
              {humanizeStatus(issue.status)}
            </Badge>

            {shouldShowPriority(issue.priority) ? (
              <Badge tone={PRIORITY_TONE[issue.priority]} size="sm">
                {humanizePriority(issue.priority)}
              </Badge>
            ) : null}

            {labels.map((label) => (
              <Badge key={label.id} tone="neutral" size="sm">
                {label.name}
              </Badge>
            ))}

            {issue.dueAt !== null ? (
              <span className={cn("text-xs", overdue && "text-red-600")}>
                {overdue ? "overdue " : "due "}
                {formatRelative(issue.dueAt)}
              </span>
            ) : null}

            {issue.archivedAt !== null ? (
              <Badge tone="warning" size="sm">
                Archived
              </Badge>
            ) : null}
          </div>
        </div>

        {assignee !== null ? (
          <Avatar name={assignee.name} src={assignee.avatarUrl} size="sm" />
        ) : (
          <Badge tone="neutral" size="sm">
            Unassigned
          </Badge>
        )}
      </div>
    </Card>
  );
}

