          <section>
            <h2 className="mb-1 font-medium text-neutral-500">Labels</h2>
            <div className="flex flex-wrap gap-1">
              {labels.map((label) => (
                <Badge key={label.id} tone="neutral" size="sm">
                  {label.name}
                </Badge>
              ))}
            </div>
          </section>
        ) : null}

        {issue.dueAt !== null ? (
