    const occurredAt = "2026-02-13T10:00:00.000Z" as IsoTimestamp;
    const summary = "Recorded between the two cut-offs";
    for (const tenant of [tokyo, utc]) {
      await activityRepo.insertActivity({
        orgId: tenant.org.id,
        action: "issue.created",
        actorId: null,
        subjectKind: "issue",
        subjectId: "retention",
        projectId: null,
        summary,
        metadata: {},
        occurredAt,
      });
    }

    await runCleanupArchivedJob(new Date("2026-03-15T16:00:00.000Z"));

    const retained = async (orgId: OrgId): Promise<number> =>
      (await activityRepo.listActivity({ orgId, limit: 100, cursor: null })).items.filter(
        (event) => event.summary === summary,
      ).length;
    expect(await retained(tokyo.org.id)).toBe(0);
    expect(await retained(utc.org.id)).toBe(1);
  });
});

